  "claude.tabApiKey": "API 密钥",
  "claude.subscriptionIntro": "推荐搭配 Pro、Max 或 Ultra 套餐使用。从此服务器（已预装 Claude Code）生成一个长期有效的令牌：",
  "claude.step1": "在服务器上打开终端（SSH）：",
  "claude.step2": "运行此命令，打开它输出的链接，用你的 Claude 账号登录并授权，然后把验证码粘贴回终端：",
