  "claude.tokenLabel": "令牌",
  "claude.keyLabel": "API 密钥",
  "claude.storedHint": "仅保存在此服务器上（仅 root 可读的机密文件），不会再次显示。",
  "claude.pasteFirst": "请先粘贴令牌。",
  "claude.authFailed": "Claude 拒绝了这些凭据。",
  "claude.connectTest": "连接并测试",
  "claude.testing": "正在向 Claude 发送测试消息…",
  "cdef.defaultModel": "默认模型",
  "cdef.cliDefault": "Claude Code 默认",
  "cdef.defaultModelHint": "会话会显示每个回合实际作答的模型。",
  "cdef.autoCompact": "自动压缩",
  "cdef.autoCompactHint": "当某个回合结束时上下文超过此阈值，Harness 会总结会话，并在以该摘要为起点的新线程中继续（类似“压缩”）：长会话不再重复发送完整历史，从而节省 token。历史记录仍会显示。",
  "cdef.autoCompactOff": "关闭",
  "cdef.autoCompactRecommended": "推荐",
  "cdef.idleCompact": "返回时压缩",
  "cdef.idleCompactHint": "Claude 的提示缓存只能保留几分钟（最长一小时）。当你在闲置更久的会话中发消息，且上下文至少达到此值时，Harness 会先对其进行总结，你的消息则在以该摘要为起点的新线程中运行：反正历史记录也要按全价重新发送，之后的回合会便宜得多。代价是回复前多一个总结回合（短暂等待）。",
  "cdef.smartResume": "智能恢复",
  "cdef.smartResumeHint": "当你回到缓存已过期的会话（见上文）且上下文至少达到此值，或闲置 5 分钟以上且上下文达到两倍时，Harness 会先让 Claude 针对你刚发送的消息总结该会话：摘要会精确保留你的消息所需的内容（文件、命令、数值、进行中的计划），然后你的消息在全新且小得多的线程中运行。在真实恢复场景中的测量结果：从 100k 起 token 减少 38% 到 67%，保留的细节也比普通摘要更好。关闭 = 仅使用上述规则。",
  "cdef.protectSecrets": "保护机密",
  "cdef.protectSecretsHint": "无论权限模式如何，Claude 的工具都会拒绝读取或修改服务器的机密（secrets.json）和 SSH 密钥（~/.ssh）。这可以防止隐藏在网页或电子邮件中的指令直接读取它们；但无法阻止专门编写来打开该文件的脚本——对于来自外部的内容，建议在该主题上使用更严格的权限模式。",
  "cdef.shortTitles": "简短会话标题",
  "cdef.shortTitlesHint": "新会话会根据第一条消息用几个词命名（去掉问候语和“你能……吗”）。关闭：标题为消息的开头部分。重命名会话始终优先。",
  "cdef.shortTitlesModel": "由 Claude 撰写标题",
  "cdef.shortTitlesModelHint": "由最小的模型概括主题（标题更准确）。每个新会话一次快速调用，计入你的 Claude 套餐。",
  "pbox.mode": "沙盒（仅限此主题）",
  "pbox.modeDesc": "Claude 在主题文件夹内自由工作，无需询问：其命令只在该文件夹内写入，无法读取服务器密钥和主目录。需要超出该范围的操作（安装软件包、重启服务、访问其他文件夹）会先询问你，并提供一个授予该主题完全访问权限的按钮。",
  "cdef.autoUpdate": "自动更新 Claude Code",
