  "infra.mail.p.spf_neutral": "{domain} 的 SPF 记录没有以 ~all 或 -all 结尾：它没有说明其他发件方的处理方式，因此任何人都可以冒充 @{domain} 发送邮件。",
  "infra.mail.f.spf_neutral": "请改为以 ~all（或 -all）结尾。",
  "infra.mail.p.dmarc_inherited_sp": "{domain} 上没有 DMARC 记录：{parent} 为其子域名设置了 sp=none，因此无论 {parent} 的 p= 为何，{domain} 都适用 p=none。",
  "infra.mail.f.dmarc_inherited_sp": "当 {domain} 的 SPF 和 DKIM 通过后，请在 {parent} 的记录中将 sp=none 改为 sp=quarantine，再改为 sp=reject；或为 {domain} 单独添加记录 _dmarc.{domain}，设置 p=quarantine。请勿降低 {parent} 的 p=。",
  "infra.mail.p.dmarc_inherited_sp_quarantine": "{domain} 上没有 DMARC 记录：{parent} 设置了 p={parent_policy}，但为其子域名设置了 sp={policy}，因此 {domain} 适用 p={policy}。",
  "infra.mail.f.dmarc_inherited_sp_quarantine": "若要让 {domain} 也适用 p={parent_policy}，请在 {parent} 的记录中将 sp={policy} 改为 sp={parent_policy}（或移除 sp=）；或为 {domain} 单独添加记录 _dmarc.{domain}，设置 p={parent_policy}。请勿降低 {parent} 的 p=。",
  "infra.mail.p.dmarc_parent_invalid": "{domain} 上没有 DMARC 记录，而 {parent} 的记录无效（{reason}）：{domain} 不适用任何 DMARC 策略。",
  "infra.mail.f.dmarc_parent_invalid": "请修复记录 _dmarc.{parent}（只保留一条带 p= 的 v=DMARC1 TXT 记录），或添加一条 TXT 记录 _dmarc.{domain}：{record}",
  "infra.mail.p.spf_redirect_all": "{domain} 的 SPF 记录通过 redirect= 转交给 {target}，而后者以 +all 结尾：任何人都可以冒充 @{domain} 发送邮件。",
  "infra.mail.f.spf_redirect_all": "请将 {domain} 的记录改为以 ~all 结尾，不再使用 redirect=，或修复 {target}。",
  "infra.mail.p.spf_loop": "{domain} 的 SPF 记录出现循环：{target} 指回了链中已有的记录，收件方会将其视为错误。",
  "infra.mail.f.spf_loop": "请移除指回链中已有记录的 include: 或 redirect=。",
  "infra.mail.p.no_spf_sender": "没有 SPF 记录：任何人都可以冒充 @{domain} 发送邮件。",
  "infra.mail.f.no_spf_sender": "请在 {domain} 上添加一条 TXT 记录，列出你用于发信的所有服务：以 {record} 为基础，在 ~all 之前加上 {sender} 的 include:（其服务商文档中有说明）。",
  "infra.mail.p.no_spf_unknown": "没有 SPF 记录：任何人都可以冒充 @{domain} 发送邮件。",
  "infra.mail.f.no_spf_unknown": "在 {domain} 上添加一条 TXT 记录，列出你用来发送邮件的所有服务。仅根据其 MX 记录，结果会是 {record}：请在 ~all 之前加入你所用发信服务的 include:（邮件服务商的文档中有说明），否则你发送的邮件将无法通过 SPF 验证。",
