  "system.cleanup.previewsDesc": "用于播放器的视频轻量副本和文件缩略图：显示时会重新生成（会占用一些 CPU）。最近 30 分钟内播放过的视频会保留。",
  "system.cleanup.trash": "Harness 回收站",
  "system.cleanup.trashDesc": "已删除的主题、会话和文件：清理后将无法再恢复。",
  "system.cleanupPrompt": "请审计这台服务器的磁盘空间，并帮我妥善地释放空间。\n\n1. 现状：运行 `df -h` 和 `free -h`，然后查看最大的文件夹（`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`），并深入检查最大的那些。设置 -> 系统 -> 释放空间已经处理了下载缓存、旧版组件、系统日志、apt 软件包、视频预览和 Harness 回收站：这些请跳过。\n2. 检查工作区中的每个项目和主题：附件、视频和音频渲染文件、导出文件、`node_modules`、Python 环境、构建产物、体积庞大的 git 仓库、被遗忘的独立副本、重复文件。也看看其他工具的缓存（`~/.cache/*`、下载的模型）、日志以及 `/tmp` 中的旧文件。\n3. 对每个大项，找出它的来源：是哪个项目、工具或定时任务创建的（日期、内容、主题的记忆、cron），以及它是否仍在增长。\n4. 给我一张按大小排序的表格：路径、大小、来源、是否会自动重新生成、你的建议（删除、移到别处、保留）以及可释放的空间。\n5. 未经我同意不要删除任何内容：把所有问题一次性问我。对于反复出现的内容，建议从根源解决（设置大小上限，或在生成它的脚本或任务中加入清理步骤）。\n6. 最后，把我们的决定（保留什么、清理什么）写入相应主题的记忆中。",
