  "pwa.steps.chrome.1": "点击地址栏右端的安装图标（一个带箭头的屏幕）。",
  "pwa.steps.chrome.2": "没有图标？打开 ⋮ 菜单 → 投放、保存和分享 → 将页面安装为应用。",
  "pwa.steps.chrome.3": "点击安装：应用会在独立窗口中打开，其图标会出现在程序坞或任务栏中。",
  "pwa.steps.edge.1": "点击地址栏右端的安装图标。",
  "pwa.steps.edge.2": "没有图标？打开 … 菜单 → 应用 → 将此站点安装为应用。",
  "pwa.steps.edge.3": "点击安装：应用会在独立窗口中打开，其图标会出现在任务栏或程序坞中。",
  "pwa.steps.safari.1": "在菜单栏中选择“文件”→“添加到程序坞”（或点击“分享”按钮 → 添加到程序坞）。需要 macOS 14 Sonoma 或更新版本。",
  "pwa.steps.safari.2": "点击添加：应用会在独立窗口中从程序坞打开。",
  "pwa.steps.firefox.1": "Firefox 无法在电脑上安装网页应用。",
  "pwa.steps.firefox.2": "在 Chrome、Edge 或 Safari 中打开此地址即可安装，或继续在标签页中使用。",
  "pwa.steps.ios.1": "在 Safari 中打开此地址（自 iOS 16.4 起，Chrome 和 Edge 也可以）。",
  "pwa.steps.ios.2": "点击“分享”按钮（带箭头的方框）。",
  "pwa.steps.ios.3": "选择“添加到主屏幕”，然后点击“添加”。",
  "pwa.steps.android.1": "在 Chrome 中打开此地址，然后打开其 ⋮ 菜单。",
  "pwa.steps.android.2": "点击“安装应用”（或“添加到主屏幕”），然后点击“安装”。",
  "pwa.steps.android.3": "应用会出现在主屏幕和应用列表中，并以全屏方式打开。",
